import pandas as pd
train = pd.read_csv('train.csv')
for lag in [1, 2, 3]:
    def acf(x):
        if len(x) > lag:
            return x.autocorr(lag)
        return 0
    print(f"lag {lag}:", train.groupby('entity_id')['target'].apply(acf).mean())
